        if (!mounted) {
          return;
        }
        setState(() {
          _samples.removeAt(0);
          // `num.clamp` returns `num`, not `double` — `_samples` is
          // `List<double>`.
          _samples.add(amplitude.clamp(0.1, 1.0).toDouble());
